    +( T_reg[2] ?  5'sd1 : -5'sd1)  // 2
    +( T_reg[1] ? -5'sd1 :  5'sd1)  // 1
    +( T_reg[0] ?  5'sd6 : -5'sd6)  // 0
  );

  wire signed [TH_WIDTH+11:0] acc_full = $signed(7 * C) + sum_terms;
  assign sat_out = $signed(acc_full) >>> 3;
  assign SOLVED  = (sat_out == $signed(C));

  reg                   read_active;
  reg                   read_active_d;
  reg [10:0] read_count;
  always @(posedge clk or posedge RESET) begin
    if (RESET) begin
      read_active   <= 1'b0;
      read_active_d <= 1'b0;
      read_count    <= 11'd0;
      T_READOUT     <= 1'b0;
    end else if (ENABLE) begin
      read_active_d <= READ;
      // start read on rising edge of READ
      if (READ & ~read_active_d)
        read_active <= 1'b1;
      // stop when READ deasserts or after NUM_CLS bits
      else if (~READ || (read_count == NUM_CLS-1))
        read_active <= 1'b0;

      if (read_active) begin
        T_READOUT <= T_reg[read_count];
        // increment but don't overflow
        if (read_count < NUM_CLS-1)
          read_count <= read_count + 1;
      end else begin
        read_count <= 11'd0;
      end
    end
  end
  wire ENABLE_INTERNAL = ENABLE && ~READ;
  solver u_solver (
    .clk        (clk),
    .RESET      (RESET),
    .ENABLE     (ENABLE_INTERNAL),
    .LOAD_T     (LOAD_T),
    .LOAD_NOISE (LOAD_NOISE),
    .RUN        (RUN),
    .T_IN       (T_IN),
    .NOISE_IN   (NOISE_IN),
    .T_reg      (T_reg)
  );

endmodule